"""Global-only discovery prompt; local discovery/review keep the frozen v010 contract."""
from copy import deepcopy
from contracts import REGION

SYSTEM = """从干净原图发现实际可见的箭头和线条，给出后续容易恢复的定位区域。
按可见线条关系和恢复难度划分区域，不按架构、重复排列或相似外观概括目标。
孤立且容易分别恢复的箭头分别定位；难以分开的相关线条可共同恢复。
只输出指定JSON、实际输入图上的绝对像素bbox和简短视觉描述，不输出路径几何。"""


def prompt(size):
    return {
        "task": "检查完整GLOBAL图，找全可见箭头/线条，按下面的粒度原则逐处给出恢复范围。",
        "global_size_px": list(size),
        "coordinate_contract": "bbox=[x1,y1,x2,y2]使用这张GLOBAL输入图的绝对像素中心坐标；左上为原点，x向右、y向下，范围[0,W-1]×[0,H-1]。不要归一化或自行换算到原图。",
        "rules": [
            "范围：linework包括普通箭头、无头连接线、曲线、虚线、括号、轴、引线及框内真实网络；block_arrow是箭身与头组成二维闭合轮廓的块状箭头，实心/空心均包括。两类分别给区域，普通箭头的三角头不单列为块状箭头。排除非箭头闭合形状的边框、格网边、字形、照片纹理；分子结构仅找外部连接。",
            "先看实际连接：相互隔开、各自起终点容易辨认的箭头分别框出。模块之间的独立短连接、不同位置的小箭头，即使排列成行列、同色或重复，也不能仅据此包成一组。",
            "需要共同上下文时可以成组：可见线段首尾衔接、共享主干/分支，或密集布线、交错曲线难以用独立bbox分清，拆开会增加框重叠、截断或连接歧义，且整体仍容易恢复时，可放在一个区域。成组可以包含独立路径，不意味着同一根箭头；首尾衔接中的不同箭头头部仍须在后续分别表达。",
            "按实际信息量判断：大量方向不同、端点需要分别辨认的独立连接，应拆为容易看清的目标或局部组。不要因为外观规则就跨越多个独立单元合组，也不要为增加框数强拆本来容易共同恢复的网络。没有固定的箭头数量或分行分列规则。",
            "逐处看图定位，不按假定的等间距复制bbox、猜测重复数量。每框包含其负责目标实际可见的箭身、头、转弯和末端；到该目标可见终点停止，不顺着流程继续吞入下一模块另一侧的箭头。不推导遮挡后的隐藏连接，交叉不自动成为连接。",
            "允许必要的bbox重叠，但本次回复里同一可见线不要重复分配；尤其不要同时保留一个交错网络大框和恢复相同笔画的子框。输出框是目标范围，不是周围上下文窗口。",
            "每个区域只需简短视觉label。group说明需要共同恢复的可见关系；不要解释架构、估计几何点或样式。label不写坐标或像素数值，数值位置只写在bbox中。",
            "single/group表示一次恢复区域的粒度，不证明物理连通。范围清楚用extent=complete；看不清范围用uncertain，不编造连接。只精简描述，不为缩短JSON而减少真实目标。",
        ],
        "output_schema": {"frame": "GLOBAL", "regions": [deepcopy(REGION)]},
    }
